"""Relatório standalone didático da inferência com proteção de seleção AIC."""
from pathlib import Path
import json
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]

def records(p):return json.loads(pd.read_csv(p).to_json(orient='records',force_ascii=False))

def build():
 data={}
 for prefix,directory,names in [
  ('old','dlm_painel_log_aic',['resultados','selecao_K','candidatos_AIC','amostras_suporte','diagnosticos','estacionariedade_uf','taxonomia','influencia_uf','autocorrelacao_uf']),
  ('new','dlm_inferencia_banda_regra_v3',['resultados','perfis','cenarios','candidatos_conferidos','coeficientes_todos_K','validacao_simulacao','sensibilidade_banda_DK','acf_scores_mensais']),
  ('close','dlm_fechamento_v4',['resumo_diagnosticos','auditoria_calibracao_rejeitada']),
  ('audit','dlm_painel_log_aic_revisao',['suporte_regressores_auditoria','condicionamento_covariancias']),
  ('gr','granger_fechamento',['matriz42','resultados','resumo','estacionariedade','coeficientes'])]:
  for name in names:data[prefix+'_'+name]=records(ROOT/'outputs/tables'/directory/(name+'.csv'))
 for name in ['new_resultados','new_perfis','new_cenarios','new_coeficientes_todos_K']:
  data[name]=[r for r in data[name] if r.get('covariancia') in ['DK_regra','DK6','DK12']]
 data['new_sensibilidade_banda_DK']=[r for r in data['new_sensibilidade_banda_DK'] if r['L'] in [3 if r['periodo']=='Pré' else 4,6,12]]
 data['manifest']={'relatorio':{'revisao':'menu lateral e síntese de todas as rejeições; 2026-10-07','covariancias_exibidas':['DK_regra','DK6','DK12'],'estimativas_e_K':'preservados; não reestimados nesta revisão'},'inferencia':json.loads((ROOT/'outputs/tables/dlm_inferencia_banda_regra_v3/manifest.json').read_text()),'fechamento':json.loads((ROOT/'outputs/tables/dlm_fechamento_v4/manifest.json').read_text())}
 target=ROOT/'outputs/reports/relatorio_tcc_fechamento_dlm_v4.html'
 packed={}
 for name,value in data.items():
  if isinstance(value,list) and value:
   cols=list(value[0]);packed[name]={'columns':cols,'rows':[[r.get(c) for c in cols] for r in value]}
  else:packed[name]=value
 target.write_text(HTML.replace('__DATA__',json.dumps(packed,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')))
 print(str(target));return target

